import React, { ButtonHTMLAttributes } from 'react';
import { StoryStack } from '@fiverr-private/storybook_helpers';
import { Button } from '@fiverr-private/button';

export interface LoadedSquareProps {
  isOpen?: boolean;
  onClick?: ButtonHTMLAttributes<HTMLButtonElement>['onClick'];
}

const LoadedSquare = ({ isOpen, onClick }: LoadedSquareProps) =>
  isOpen ? (
    <StoryStack alignItems="center" justifyContent="center" padding="10" backgroundColor="green_700">
      <Button onClick={onClick}>Close</Button>
    </StoryStack>
  ) : null;

export default LoadedSquare;
